//         readback (model read-back), trap (optional: {q, opts:[...], ok:index, why}) }
// All names, numbers and extensions are invented. Doses and toxicology advice are typical, from memory — see MANIFEST "facts to check".
const L10_TEL_TYPES={labor:"Labor",pflege:"Pflege nachts",radio:"Radiologie",hausarzt:"Hausarzt",angeh:"Angehörige",apo:"Apotheke",leit:"Leitstelle",oa:"Oberarzt-Rückruf",betten:"Bettenmanagement",gift:"Giftnotruf"};
